	/**
	 * Get auto-hooks summary for a site relation
	 *
	 * Returns a summary of hooks that would be auto-generated for a relation.
	 *
	 * @since 0.6.0
	 *
	 * @param int $relation_id Site relation ID.
	 * @return array Summary with counts and hook details.
	 */
	public static function get_relation_hooks_summary( $relation_id ) {
		$relation = \WPTSALL\Sites\Services\Site_Relation_Service::get_relation( $relation_id );
		if ( ! $relation ) {
			return array(
				'error'   => 'Relation not found',
				'total'   => 0,
				'models'  => array(),
			);
		}

		$models = \WPTSALL\Sites\Services\Relation_Model_Service::get_models_by_relation( $relation_id );
		$is_virtual_target = ( $relation['target_site_type'] ?? '' ) === 'virtual';
		$is_wp_source      = ( $relation['source_site_type'] ?? 'wp' ) === 'wp';

		$summary = array(
			'relation_id'       => $relation_id,
			'target_type'       => $is_virtual_target ? 'virtual' : 'wp',
			'source_type'       => $is_wp_source ? 'wp' : 'other',
			'models_count'      => count( $models ),
			'total_hooks'       => 0,
			'post_type_hooks'   => 0,
			'taxonomy_hooks'    => 0,
			'frontend_hooks'    => 0,
			'models'            => array(),
		);

		foreach ( $models as $model ) {
			$model_hooks = self::generate_model_hooks( $relation, $model, $is_virtual_target, $is_wp_source );
			$model_summary = array(
				'model_id'     => $model['id'] ?? 0,
				'plugin_name'  => $model['plugin_name'] ?? '',
				'plugin_slug'  => $model['plugin_slug'] ?? '',
				'hooks_count'  => count( $model_hooks ),
				'post_types'   => array(),
				'taxonomies'   => array(),
			);

			// Parse model objects for summary.
			$post_types = self::parse_model_objects( $model['post_types'] ?? array() );
			$taxonomies = self::parse_model_objects( $model['taxonomies'] ?? array() );

			foreach ( $post_types as $pt ) {
				$model_summary['post_types'][] = is_array( $pt ) ? ( $pt['name'] ?? '' ) : $pt;
			}

			foreach ( $taxonomies as $tax ) {
				$model_summary['taxonomies'][] = is_array( $tax ) ? ( $tax['name'] ?? '' ) : $tax;
			}

			// Count hook types.
			foreach ( $model_hooks as $hook ) {
				$hook_name = $hook['hook_name'] ?? '';
				if ( str_starts_with( $hook_name, 'save_post' ) || in_array( $hook_name, array( 'delete_post', 'trash_post', 'edit_attachment', 'set_object_terms' ), true ) || self::is_post_meta_hook_name( $hook_name ) ) {
					$summary['post_type_hooks']++;
				} elseif ( in_array( $hook_name, array( 'created_term', 'edited_term', 'delete_term' ), true ) ) {
					$summary['taxonomy_hooks']++;
				} elseif ( self::is_frontend_delivery_hook( $hook_name ) ) {
					$summary['frontend_hooks']++;
				}
			}

			$summary['total_hooks'] += count( $model_hooks );
			$summary['models'][]     = $model_summary;
		}

		return $summary;
	}

	/**
	 * Clear registered hooks cache
	 *
	 * Useful when hooks need to be re-registered after model changes.
	 *
	 * @since 0.6.0
	 *
	 * @return void
	 */
	public static function clear_registered_cache() {
		self::$registered = array();

		wptsall_log_info(
			'hooks-manager',
			'Registered hooks cache cleared'
		);
	}

	/**
	 * Get hooks for a specific model
	 *
	 * @since 0.6.0
	 *
	 * @param int $model_id Model ID.
	 * @return array Hooks data.
	 */
	public static function get_hooks_for_model( $model_id ) {
		$model = self::get_model_by_id( $model_id );
		if ( ! $model ) {
			return array();
		}

		// Get all relations that include this model.
		$relations = \WPTSALL\Sites\Services\Relation_Model_Service::get_relations_by_model( $model_id );

		$all_hooks = array();
		foreach ( $relations as $relation ) {
			$is_virtual_target = ( $relation['target_site_type'] ?? '' ) === 'virtual';
			$is_wp_source      = ( $relation['source_site_type'] ?? 'wp' ) === 'wp';

			$hooks = self::generate_model_hooks( $relation, $model, $is_virtual_target, $is_wp_source );
			$all_hooks = array_merge( $all_hooks, $hooks );
		}

		return $all_hooks;
	}

	/**
	 * Get plugin-specific hooks for a model
	 *
	 * Returns plugin-specific hooks (like WooCommerce hooks) that should be
	 * registered in addition to standard hooks.
	 *
	 * @since 0.6.0
	 *
	 * @param array $model     Model data.
	 * @param array $relation  Site relation data.
	 * @return array Additional hooks.
	 */
	public static function get_plugin_specific_hooks( $model, $relation ) {
		$model_id     = (int) ( $model['id'] ?? 0 );
		$plugin_slug  = $model['plugin_slug'] ?? '';
		$relation_id  = (int) $relation['id'];
		$additional_hooks = array();

		// 1. First try to get hooks from database (generated by Model_Scanner_V2 scan)
		if ( $model_id > 0 && class_exists( '\\WPTSALL\\Models\\Services\\Translation_Rule_Service' ) ) {
			$db_hooks = \WPTSALL\Models\Services\Translation_Rule_Service::get_hooks_by_model( $model_id );

			if ( ! empty( $db_hooks ) ) {
				foreach ( $db_hooks as $hook ) {
					$additional_hooks[] = array(
						'hook_name' => $hook['hook_name'],
						'site_id'   => $relation_id,
						'model_id'  => $model_id,
						'template'  => $plugin_slug,
						'status'    => 'enabled',
						'priority'  => $hook['priority'] ?? 10,
						'expected'  => array(
							'object_type' => $hook['data_type'] === 'post' ? 'post_type' : 'taxonomy',
							'subtype'     => $hook['object_name'],
						),
						'source'    => 'database',
						'action'    => $hook['action'] ?? 'update',
					);
				}

				wptsall_log_debug(
					'hooks-manager',
					'Loaded hooks from database',
					array(
						'model_id'    => $model_id,
						'plugin_slug' => $plugin_slug,
						'hook_count'  => count( $additional_hooks ),
					)
				);

				return $additional_hooks;
			}
		}

		// If no hook configuration in database, return empty array
		// Hook configuration should be saved to database during model scan or manual configuration
		return $additional_hooks;
	}
}
